const { fonte, janela } = $json;
const versaoApi = 'v23.0';
const FUSO = 'America/Sao_Paulo';
const datasetId = String(fonte?.externalId ?? '');

function deslocamento(instante) {
  const partes = new Intl.DateTimeFormat('en-US', {
    timeZone: FUSO, hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', second: '2-digit',
  }).formatToParts(instante);
  const valor = (tipo) => Number(partes.find((parte) => parte.type === tipo)?.value);
  const comoUtc = Date.UTC(valor('year'), valor('month') - 1, valor('day'), valor('hour'), valor('minute'), valor('second'));
  return comoUtc - Math.floor(instante.getTime() / 1000) * 1000;
}

function meiaNoite(dia) {
  const [ano, mes, diaDoMes] = dia.split('-').map(Number);
  const ingenuo = Date.UTC(ano, mes - 1, diaDoMes);
  const primeira = ingenuo - deslocamento(new Date(ingenuo));
  return Math.floor((ingenuo - deslocamento(new Date(primeira))) / 1000);
}

const [ano, mes, dia] = janela.end.split('-').map(Number);
const diaSeguinte = new Date(Date.UTC(ano, mes - 1, dia + 1)).toISOString().slice(0, 10);
const startTime = meiaNoite(janela.start);
const endTime = meiaNoite(diaSeguinte);
const base = `https://graph.facebook.com/${versaoApi}/${encodeURIComponent(datasetId)}/stats?aggregation=event&start_time=${startTime}&end_time=${endTime}`;

return [{
  json: {
    inicio: Date.now(),
    versaoApi,
    janela,
    datasetIdValido: /^\d{5,25}$/.test(datasetId),
    startTime,
    endTime,
    urls: {
      total: base,
      navegador: `${base}&event_source=WEB_ONLY`,
      servidor: `${base}&event_source=SERVER_ONLY`,
    },
  },
}];

const contexto = $('Montar requisição').first().json;
const FUSO = 'America/Sao_Paulo';
const ORIGENS = ['total', 'navegador', 'servidor'];
const NO_DA_ORIGEM = { total: 'Eventos (total)', navegador: 'Eventos (navegador)', servidor: 'Eventos (servidor)' };
const TAMANHO_MAXIMO_DO_EVENTO = 200;

const respostasPorOrigem = {};
for (const origem of ORIGENS) {
  respostasPorOrigem[origem] = $(NO_DA_ORIGEM[origem]).all()
    .map((item) => item.json)
    .filter((json) => json && (json.statusCode !== undefined || json.error));
}
const todas = ORIGENS.flatMap((origem) => respostasPorOrigem[origem]);
const requests = todas.length;
const bytes = todas.reduce((total, resposta) => total + JSON.stringify(resposta.body ?? {}).length, 0);

function devolver(linhas, falhas) {
  return [{
    json: {
      linhas,
      volumetria: { linhas: linhas.length, bytes, requests, duracaoMs: Date.now() - contexto.inicio },
      falhas,
      requests,
      versaoApi: contexto.versaoApi,
    },
  }];
}

function falhaDe(respostas) {
  if (respostas.length === 0) return { causa: 'api_recusou', detalhe: 'a Meta não respondeu' };
  const deRede = respostas.find((resposta) => resposta.error);
  if (deRede) {
    const detalhe = deRede.error?.message ?? String(deRede.error);
    return { causa: 'api_recusou', detalhe: `falha de rede: ${detalhe}`.replace(/access_token=[^&\s"']+/g, 'access_token=[removido]').slice(0, 500) };
  }
  const recusada = respostas.find((resposta) => !(resposta.statusCode >= 200 && resposta.statusCode < 300));
  if (!recusada) return null;
  const erro = recusada.body?.error;
  const detalhe = String(erro?.message || `HTTP ${recusada.statusCode}`).slice(0, 500);
  const semAcesso = recusada.statusCode === 401 || recusada.statusCode === 403 || [190, 10, 200].includes(erro?.code);
  return { causa: semAcesso ? 'reauth_pending' : 'api_recusou', detalhe };
}

if (!contexto.datasetIdValido) return devolver([], [{ causa: 'api_recusou', detalhe: 'id do conjunto de dados inválido' }]);

const falhaDoTotal = falhaDe(respostasPorOrigem.total);
if (falhaDoTotal) return devolver([], [falhaDoTotal]);

const formatoDoDia = new Intl.DateTimeFormat('en-CA', { timeZone: FUSO, year: 'numeric', month: '2-digit', day: '2-digit' });

function instanteDoBalde(valor) {
  if (typeof valor === 'number' && Number.isFinite(valor)) return new Date(valor * 1000);
  if (typeof valor !== 'string' || !valor) return null;
  if (/^\d+$/.test(valor)) return new Date(Number(valor) * 1000);
  const data = new Date(valor.replace(/([+-]\d{2})(\d{2})$/, '$1:$2'));
  return Number.isNaN(data.getTime()) ? null : data;
}

function nomeDoEvento(valor) {
  if (typeof valor !== 'string') return null;
  const limpo = valor.trim();
  return limpo ? limpo.slice(0, TAMANHO_MAXIMO_DO_EVENTO) : null;
}

function contagem(valor) {
  const numero = typeof valor === 'string' && valor.trim() !== '' ? Number(valor) : valor;
  return typeof numero === 'number' && Number.isFinite(numero) && numero >= 0 ? Math.trunc(numero) : null;
}

function agregar(respostas, origem) {
  const somas = new Map();
  for (const resposta of respostas) {
    const baldes = Array.isArray(resposta.body?.data) ? resposta.body.data : [];
    for (const balde of baldes) {
      const instante = instanteDoBalde(balde?.start_time);
      if (!instante || !Array.isArray(balde.data)) continue;
      const dataDia = formatoDoDia.format(instante);
      if (dataDia < contexto.janela.start || dataDia > contexto.janela.end) continue;
      for (const item of balde.data) {
        const evento = nomeDoEvento(item?.value);
        const quantidade = contagem(item?.count);
        if (!evento || quantidade === null) continue;
        const chave = `${dataDia}|${evento}`;
        const anterior = somas.get(chave);
        somas.set(chave, { dataDia, evento, origem, quantidade: (anterior?.quantidade ?? 0) + quantidade });
      }
    }
  }
  return [...somas.values()];
}

const linhas = [];
const origensIncompletas = [];
for (const origem of ORIGENS) {
  const falha = origem === 'total' ? null : falhaDe(respostasPorOrigem[origem]);
  if (falha) {
    origensIncompletas.push(`${origem}: ${falha.detalhe}`);
    continue;
  }
  linhas.push(...agregar(respostasPorOrigem[origem], origem));
}

if (!linhas.some((linha) => linha.origem === 'total')) return devolver([], [{ causa: 'sem_dados_no_periodo', detalhe: null }]);
if (origensIncompletas.length > 0) {
  return devolver(linhas, [{ causa: 'coleta_incompleta', detalhe: `recorte por origem indisponível: ${origensIncompletas.join('; ')}`.slice(0, 500) }]);
}
return devolver(linhas, []);
